"""
MedFlow synthetic newborn records — SOURCE DATA (fictional people, fictional events).

Two strictly separate structures per baby:
  RAW      -> becomes baby_dataset.json / babies table (the only thing AI may ever see)
  EXPECTED -> becomes expected_requirements.json / baby_expected_* tables (evaluation only)

Writing rules enforced by validate_dataset.py:
  * Raw text never contains catalogue codes (EQ_*, FAC_*, SP_*, NICU_*), NICU level
    labels, or priority words ("urgent", "emergency", "priority").
  * Age is never typed by hand: it is computed from date_of_birth and REFERENCE_DATE.
"""

REFERENCE_DATE = "2026-10-31"
DEFAULT_CURRENT_HOSPITAL = "HOSP001"   # fictional Demo Referral Centre


def baby(code, name, sex, dob, ga, bw, cw, category, *, history, summary, symptoms,
         notes, oxygen, care, reason, expected):
    ga_w, ga_d = ga
    mode, fio2, flow, o2_notes = oxygen
    level, bed, equipment, facilities, specialists, priority = expected
    return {
        "raw": {
            "baby_code": code, "full_name": name, "sex": sex, "date_of_birth": dob,
            "gestational_age_weeks": ga_w, "gestational_age_days": ga_d,
            "birth_weight_g": bw, "current_weight_g": cw,
            "medical_history": history, "condition_summary": summary,
            "symptoms": symptoms, "clinical_notes": notes,
            "oxygen_support": {"mode": mode, "fio2": fio2, "flow_lpm": flow, "notes": o2_notes},
            "current_care": care, "current_hospital_id": DEFAULT_CURRENT_HOSPITAL,
            "transfer_reason": reason,
        },
        "category": category,
        "expected": {
            "required_nicu_level": level, "required_bed_type": bed,
            "required_equipment": equipment, "required_care_facilities": facilities,
            "required_specialists": specialists, "expected_priority": priority,
        },
    }


